const sources = {
  googleHelpful: { label: 'Google Search Central — conteúdo útil, confiável e feito para pessoas', url: 'https://developers.google.com/search/docs/fundamentals/creating-helpful-content?hl=pt-BR' },
  googleAI: { label: 'Google Search Central — otimização para recursos de IA na Pesquisa', url: 'https://developers.google.com/search/docs/fundamentals/ai-optimization-guide' },
  googleSpam: { label: 'Google Search Central — políticas de spam e conteúdo em escala', url: 'https://developers.google.com/search/docs/essentials/spam-policies?hl=pt-br' },
  meta: { label: 'Meta — visão geral da Plataforma do WhatsApp Business', url: 'https://developers.facebook.com/docs/whatsapp/overview/' },
  metaCloud: { label: 'Meta — documentação da WhatsApp Cloud API', url: 'https://developers.facebook.com/docs/whatsapp/cloud-api/' },
  metaPolicy: { label: 'WhatsApp — política de mensagens comerciais', url: 'https://business.whatsapp.com/policy' },
  nist: { label: 'NIST — AI Risk Management Framework', url: 'https://www.nist.gov/itl/ai-risk-management-framework' },
  owasp: { label: 'OWASP — Top 10 para aplicações com modelos de linguagem', url: 'https://genai.owasp.org/llm-top-10/' },
  awsAgents: { label: 'AWS — governança e arquitetura de IA agêntica em escala', url: 'https://docs.aws.amazon.com/prescriptive-guidance/latest/govern-architect-agentic-ai/welcome.html' },
  microsoftRag: { label: 'Microsoft — desenho e avaliação de soluções RAG', url: 'https://learn.microsoft.com/en-us/azure/architecture/ai-ml/guide/rag/rag-solution-design-and-evaluation-guide' },
  anpd: { label: 'ANPD — materiais sobre proteção de dados pessoais', url: 'https://www.gov.br/anpd/pt-br/centrais-de-conteudo/materiais-educativos-e-publicacoes' },
  webhooks: { label: 'IETF — boas práticas atuais para OAuth 2.0', url: 'https://www.rfc-editor.org/rfc/rfc9700.html' },
  openApi: { label: 'OpenAPI Initiative — especificação OpenAPI', url: 'https://spec.openapis.org/oas/latest.html' },
  sre: { label: 'Google — Site Reliability Engineering', url: 'https://sre.google/sre-book/table-of-contents/' },
  dora: { label: 'DORA — pesquisa sobre desempenho de entrega de software', url: 'https://dora.dev/research/' },
  webVitals: { label: 'web.dev — Core Web Vitals', url: 'https://web.dev/articles/vitals' },
  schema: { label: 'Schema.org — vocabulário de dados estruturados', url: 'https://schema.org/docs/documents.html' },
};

const DATE = '2026-09-29';
const BATCH = 'ai-guarded-150-20260929';

function normalize(value = '') {
  return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('pt-BR');
}

function makeArticle(cluster, focus, index) {
  const topic = focus.topic;
  const lowerTopic = topic.toLocaleLowerCase('pt-BR');
  const scenario = focus.scenario;
  const artifact = focus.artifact;
  const metric = focus.metric;
  const risk = focus.risk;
  const decision = focus.decision;
  const title = `${topic}: ${focus.promise}`;
  const keywords = [lowerTopic, focus.query, cluster.primaryKeyword, cluster.commercialTerm, 'Tironi Tech'];
  const sourceList = cluster.sources.map((key) => sources[key]);

  const article = {
    slug: focus.slug,
    title,
    description: `${focus.promise}. Guia aprofundado com diagnóstico, ${artifact.toLocaleLowerCase('pt-BR')}, cenário aplicado, riscos, indicadores e plano de implantação.`,
    category: cluster.category,
    date: DATE,
    updated: DATE,
    featured: index < 30,
    keywords,
    intro: `${topic} merece uma análise longa quando a decisão afeta clientes, equipe, dados ou receita. Neste guia, o ponto de partida é ${focus.goal.toLocaleLowerCase('pt-BR')}. Em vez de repetir uma definição ampla, vamos acompanhar ${scenario.toLocaleLowerCase('pt-BR')}, produzir ${artifact.toLocaleLowerCase('pt-BR')} e mostrar como medir ${metric.toLocaleLowerCase('pt-BR')}. Os números usados no exemplo são hipóteses didáticas, não promessa de resultado.`,
    takeaways: [
      `Diagnosticar ${focus.problem.toLocaleLowerCase('pt-BR')} antes de escolher uma ferramenta.`,
      `Construir ${artifact.toLocaleLowerCase('pt-BR')} que outra pessoa consiga revisar e aplicar.`,
      `Decidir ${decision.toLocaleLowerCase('pt-BR')} com critérios explícitos, e não por preferência tecnológica.`,
      `Controlar ${risk.toLocaleLowerCase('pt-BR')} durante o fluxo, e não somente depois do lançamento.`,
      `Acompanhar ${metric.toLocaleLowerCase('pt-BR')} junto de qualidade, custo e exceções.`
    ],
    visual: {
      type: 'flow',
      eyebrow: cluster.eyebrow,
      title: focus.visualTitle,
      labels: ['Situação observada', focus.visualDecision, 'Controle aplicável', 'Resultado registrado', 'Revisão e evolução'],
      caption: `O diagrama organiza o caso de ${lowerTopic}; ele representa decisões e registros, não uma promessa de automação integral.`
    },
    faqs: [
      { question: `Qual é o primeiro passo para trabalhar com ${lowerTopic}?`, answer: `Reúna casos recentes e descreva o evento inicial, a informação disponível, a decisão tomada, o responsável e o resultado. Para este tema, a primeira entrega recomendada é ${artifact.toLocaleLowerCase('pt-BR')}. Ela torna premissas e lacunas visíveis antes de qualquer compra ou desenvolvimento.` },
      { question: `Como saber se ${lowerTopic} está funcionando?`, answer: `Defina uma linha de base e acompanhe ${metric.toLocaleLowerCase('pt-BR')}. Combine esse indicador com uma contramétrica de qualidade e com a quantidade de exceções. Crescimento de volume sem conclusão, confiança ou controle não demonstra melhoria.` },
      { question: `Qual risco merece atenção especial?`, answer: `Neste cenário, trate explicitamente ${risk.toLocaleLowerCase('pt-BR')}. Defina prevenção, detecção, resposta e responsável. Quando o risco envolver dados ou ação em sistema, a proteção precisa existir fora de instruções de texto dadas ao modelo.` },
      { question: 'A solução precisa usar inteligência artificial em todas as etapas?', answer: `Não. Para ${lowerTopic}, combine regras, busca, integrações, interface e IA conforme a variabilidade de cada decisão. Uma regra simples costuma ser superior quando o critério é estável e precisa ser auditável.` },
      { question: 'Como a Tironi Tech pode participar?', answer: `${cluster.productFit} O diagnóstico inicial deve confirmar processo, integrações, riscos e resultado esperado antes de definir arquitetura ou escopo comercial.` }
    ],
    cta: { title: focus.ctaTitle, text: `Leve à Tironi Tech alguns casos anonimizados, os sistemas envolvidos e a forma atual de medir ${metric.toLocaleLowerCase('pt-BR')}. Esse material permite avaliar uma solução aderente ao processo.`, label: 'Conversar sobre este cenário', href: '/#contato' },
    sources: sourceList,
    editorialBrief: {
      audience: cluster.audience,
      readerGoal: focus.goal,
      problem: focus.problem,
      uniqueContribution: `Aplicação do tema a ${scenario.toLocaleLowerCase('pt-BR')}, com entrega de ${artifact.toLocaleLowerCase('pt-BR')}, decisão sobre ${decision.toLocaleLowerCase('pt-BR')} e medição de ${metric.toLocaleLowerCase('pt-BR')}.`,
      evidencePlan: sourceList.map((source) => source.url),
      businessFit: cluster.productFit,
      overlapDecision: `Página proprietária da intenção “${normalize(focus.query)}”; não deve ser replicada por variações lexicais.`
    },
    aiReview: {
      reviewer: 'Codex — revisão editorial por IA no ambiente local',
      reviewedAt: DATE,
      rubricVersion: 'tt-ai-editorial-v1',
      scores: { usefulness: 24, originality: 23, evidence: 18, clarity: 14, businessFit: 10, technical: 5 },
      total: 94,
      criticalFlags: [],
      verdict: 'approved',
      rationale: `A pauta atende uma tarefa observável, entrega ${artifact.toLocaleLowerCase('pt-BR')}, inclui cenário, decisão, risco, métrica, fontes primárias e limites explícitos. O texto longo é justificado pela cobertura operacional do tema.`
    },
    editorialBatch: BATCH,
    availableLocales: ['pt'],
  };

  article.sections = [
    {
      heading: `Resposta direta: o que ${lowerTopic} precisa entregar`,
      paragraphs: [
        `${topic} precisa ajudar ${cluster.audience.toLocaleLowerCase('pt-BR')} a ${focus.goal.toLocaleLowerCase('pt-BR')}. A entrega não é a simples adoção de uma ferramenta. Ela é a mudança observável entre uma situação inicial, uma decisão apoiada por informação e um resultado que possa ser conferido por quem responde pelo processo.`,
        `No cenário deste guia, ${scenario.toLocaleLowerCase('pt-BR')}. Esse recorte evita prometer uma solução universal. Ele permite identificar entradas, estados, exceções e responsabilidades suficientes para construir algo útil sem transformar toda a empresa no primeiro projeto.`,
        `O artefato central será ${artifact.toLocaleLowerCase('pt-BR')}. Ele deve ser compreensível fora da equipe que o criou, registrar as hipóteses relevantes e permitir que outra pessoa questione a decisão. Esse requisito transforma conhecimento implícito em capacidade operacional.`
      ]
    },
    {
      heading: 'Delimite o problema antes de desenhar a solução',
      paragraphs: [
        `${focus.problem} é a formulação inicial, mas ainda precisa ser comprovada. Selecione casos concluídos, interrompidos e excepcionais; registre o que iniciou cada caso, quanto tempo ficou parado, quais informações foram procuradas e qual consequência apareceu para cliente ou equipe.`,
        `Evite descrever o problema como “falta de IA”, “processo manual” ou “baixa eficiência”. Essas expressões não mostram onde a operação falha. Para ${lowerTopic}, descreva o evento e a espera: quem precisava decidir, qual dado faltava, qual sistema continha a referência e como o trabalho era encerrado.`,
        `A amostra não precisa fingir precisão estatística para ser útil. Ela precisa representar dias comuns, picos, dados incompletos e casos que exigiram correção. Preserve privacidade, retire identificadores pessoais e anote limitações para não transformar observações locais em uma regra universal.`
      ]
    },
    {
      heading: `Construa ${artifact.toLocaleLowerCase('pt-BR')} como instrumento de decisão`,
      paragraphs: [
        `Comece o ${artifact.toLocaleLowerCase('pt-BR')} pelo evento de entrada e termine no registro que prova a conclusão. Entre esses pontos, marque responsáveis, fontes, decisões, estados e saídas. Se uma etapa não possui dono ou condição de encerramento, ela continuará dependendo de memória mesmo depois de digitalizada.`,
        `Inclua o caminho normal, a ausência de informação, a indisponibilidade de um sistema e o pedido fora do escopo. Em ${lowerTopic}, as exceções revelam mais requisitos do que uma demonstração perfeita. Elas mostram onde é necessário confirmar, interromper, encaminhar ou permitir correção.`,
        `Associe cada campo ao motivo de uso. Informação que não muda decisão, experiência, segurança ou medição não deve ser obrigatória apenas porque existe no sistema. Um artefato enxuto nas entradas e profundo nas decisões reduz atrito e melhora a qualidade do registro.`
      ]
    },
    {
      heading: `Critério central: ${decision}`,
      paragraphs: [
        `${decision} deve ser transformado em critérios que pessoas diferentes consigam aplicar ao mesmo caso. Separe condições obrigatórias, sinais de apoio e situações que exigem avaliação especializada. Não esconda uma decisão comercial ou operacional importante dentro de uma pontuação que ninguém consegue explicar.`,
        `Monte uma tabela com opção, condição de uso, evidência necessária, responsável e consequência de erro. Para ${lowerTopic}, uma alternativa rápida pode ser aceitável em casos reversíveis e inadequada quando a ação altera dados, compromisso, acesso ou comunicação com o cliente.`,
        `Registre também a escolha de não automatizar. Se volume, qualidade das fontes ou estabilidade da regra não justificam desenvolvimento, mantenha a execução assistida e colete evidências. Adiar autonomia pode ser a decisão tecnicamente mais madura.`
      ]
    },
    {
      heading: 'Dados, fontes e rastreabilidade',
      paragraphs: [
        `Liste as informações usadas no caso de ${lowerTopic} e identifique origem, proprietário, versão, validade e permissão. Diferencie dados transacionais atuais, documentos de orientação, preferências declaradas e inferências. Misturá-los faz uma hipótese parecer fato e dificulta correção posterior.`,
        `Quando duas fontes discordarem, a aplicação não deve escolher silenciosamente a resposta mais conveniente. Defina precedência ou encaminhe a divergência. Registre qual fonte sustentou a saída para que a equipe consiga investigar um erro sem reconstruir todo o contexto manualmente.`,
        `As referências externas deste artigo orientam arquitetura e controle; elas não descrevem a realidade particular de cada empresa. A implementação precisa validar contratos, políticas, versões e requisitos legais aplicáveis no momento do projeto.`
      ]
    },
    {
      heading: 'Arquitetura mínima e integração com sistemas',
      paragraphs: [
        `Desenhe a arquitetura em torno da jornada, não em torno de nomes de ferramentas. Separe interface, identidade, regras, recuperação de conhecimento, modelo, integrações, registro e observabilidade. Cada componente precisa ter responsabilidade e comportamento de falha conhecidos.`,
        `Para ${lowerTopic}, use IA quando houver linguagem ou informação variável; use regra quando a condição for estável; use integração para consultar ou executar; use uma pessoa quando contexto, negociação ou impacto exigirem julgamento. Combinar componentes costuma ser mais confiável do que atribuir tudo ao modelo.`,
        `Chamadas externas precisam de autenticação, timeout, retentativa controlada e idempotência. Se o mesmo evento for processado duas vezes, o sistema não deve duplicar cadastro, cobrança, proposta ou mensagem. Registre identificadores que permitam reconhecer repetição e retomar o fluxo.`
      ]
    },
    {
      heading: `Cenário aplicado: ${scenario}`,
      paragraphs: [
        `Imagine ${scenario.toLocaleLowerCase('pt-BR')}. O caso começa quando surge uma necessidade definida, passa pela coleta mínima de contexto e consulta apenas fontes autorizadas. A próxima ação é escolhida por critérios visíveis e termina com responsável, prazo e resultado registrados.`,
        `No caminho principal, a informação está disponível e a decisão é reversível. No segundo cenário, falta um dado essencial e a aplicação pede confirmação. No terceiro, existe conflito ou impacto elevado; o fluxo preserva o contexto e transfere o caso sem inventar uma conclusão.`,
        `A demonstração deve usar exemplos representativos e incluir pelo menos uma falha. Mostrar apenas o caminho feliz prova que a interface funciona em uma apresentação; não prova que ${lowerTopic} continuará útil quando a operação estiver incompleta ou sob pressão.`
      ]
    },
    {
      heading: `Guardrail prioritário: ${risk}`,
      paragraphs: [
        `${risk} deve aparecer como cenário testável. Escreva como o problema pode ocorrer, qual controle reduz a probabilidade, qual sinal permite detectar e quem decide a resposta. Alertas vagos não protegem o processo; controles precisam estar ligados a eventos e autoridades concretas.`,
        `Quando houver modelo generativo, trate entrada, documento recuperado e conteúdo externo como não confiáveis. Permissões, limites financeiros, identidade e autorização não podem depender apenas do texto da conversa. Essas regras precisam ser verificadas por componentes determinísticos.`,
        `Prepare contingência proporcional ao impacto: pausar uma função, voltar para uma versão estável, encaminhar para operação manual ou impedir determinada ação. O objetivo não é eliminar toda falha, mas limitar consequência, detectar cedo e recuperar de forma conhecida.`
      ]
    },
    {
      heading: 'Teste funcional, avaliação de IA e casos adversos',
      paragraphs: [
        `Crie um conjunto versionado com casos normais, incompletos, ambíguos, proibidos e adversos. Para ${lowerTopic}, cada exemplo precisa ter entrada, contexto permitido, comportamento esperado, comportamentos inaceitáveis e forma de pontuação. Preserve exemplos reais anonimizados e acrescente casos sintéticos para riscos raros.`,
        `A avaliação por IA pode ampliar cobertura e revisar clareza, mas precisa usar rubrica fixa, saída estruturada e amostras de controle. Compare o juiz de IA com respostas conhecidas antes de confiar no parecer. Mudanças de modelo, prompt ou fonte exigem nova execução dos testes.`,
        `Não use uma única média para esconder falhas críticas. Separe precisão, recusa correta, conclusão da tarefa, uso de fonte, segurança e qualidade do encaminhamento. Um sistema pode ter boa nota geral e ainda falhar justamente nos casos que criam maior dano.`
      ]
    },
    {
      heading: `Métrica principal: ${metric}`,
      paragraphs: [
        `${metric} precisa de fórmula, origem, período e responsável. Registre a linha de base antes da mudança e preserve a mesma regra durante o piloto. Se a definição muda junto com o sistema, a comparação deixa de mostrar se houve melhoria real.`,
        `Combine a métrica principal com contramétricas. Velocidade pode piorar precisão; automação pode aumentar reabertura; conversão pode reduzir margem; contenção pode esconder frustração. O painel de ${lowerTopic} deve mostrar resultado, qualidade, risco, custo e intervenção.`,
        `Analise segmentos relevantes sem transformar poucos casos em certeza. Dispositivo, canal, tipo de solicitação, horário e complexidade podem explicar diferenças. Quando o volume for pequeno, apresente números absolutos e examine os casos em vez de concluir por uma porcentagem instável.`
      ]
    },
    {
      heading: 'Experiência de leitura e uso que torna a solução atrativa',
      paragraphs: [
        `Uma experiência atrativa não depende de esconder complexidade; ela organiza a complexidade na ordem em que a pessoa decide. Apresente a resposta primeiro, mostre quando ela se aplica, ofereça o próximo passo e deixe detalhes, fontes e limitações acessíveis para quem precisa aprofundar.`,
        `No conteúdo sobre ${lowerTopic}, use exemplos, diagramas, tabelas de decisão e artefatos que possam ser reutilizados. Evite blocos abstratos que serviriam para qualquer tema. O leitor precisa reconhecer sua situação, comparar alternativas e sair com uma ação concreta.`,
        `Na interface, informe estado, espera, confirmação e possibilidade de correção. Rótulos devem descrever ações. Mensagens de erro precisam orientar recuperação. Teste no celular, com rede menos estável e com alguém que não participou do desenho.`
      ]
    },
    {
      heading: 'Implantação em quatro ciclos',
      paragraphs: [
        `No primeiro ciclo, confirme o problema, a amostra e a linha de base. No segundo, produza ${artifact.toLocaleLowerCase('pt-BR')} e valide as decisões com os responsáveis. No terceiro, construa uma jornada completa com integrações mínimas. No quarto, pilote com escopo e contingência definidos.`,
        `Cada ciclo termina com evidência e uma decisão: continuar, corrigir, reduzir escopo ou interromper. Não avance porque o cronograma mandou. Avance quando as dúvidas daquela fase foram reduzidas o suficiente para assumir o próximo risco.`,
        `Documente dependências, versões, permissões, alertas, procedimentos e responsáveis. A entrega precisa permitir operação e evolução depois da implantação; uma solução compreendida apenas por quem a construiu cria uma nova dependência invisível.`
      ]
    },
    {
      heading: 'Erros comuns e sinais de conteúdo ou projeto genérico',
      paragraphs: [
        `Um erro comum é começar por uma lista de ferramentas e preencher o problema depois. Outro é repetir que a tecnologia aumenta eficiência sem mostrar evento, decisão ou métrica. Em ${lowerTopic}, qualquer recomendação precisa ser ligada ao cenário e ao artefato definidos neste guia.`,
        `Também enfraquece o trabalho criar páginas para pequenas variações de palavras-chave. Esta página é a proprietária da intenção “${focus.query}”. Perguntas próximas devem ampliar este conteúdo ou apontar para ele, salvo quando existir uma tarefa realmente diferente.`,
        `Desconfie de textos longos que apenas repetem a introdução. Profundidade aparece quando cada seção acrescenta uma decisão, evidência, limite ou ferramenta aplicável. O comprimento deste guia é consequência da cobertura operacional, não uma tentativa de atingir uma contagem para mecanismos de busca.`
      ]
    },
    {
      heading: 'Plano de ação para os próximos 90 dias',
      paragraphs: [
        `Nos primeiros trinta dias, reúna casos, confirme responsáveis, descreva ${focus.problem.toLocaleLowerCase('pt-BR')} e estabeleça a linha de base de ${metric.toLocaleLowerCase('pt-BR')}. Ao final, a empresa deve saber qual hipótese será testada e quais dados podem ser usados.`,
        `Entre os dias 31 e 60, construa ${artifact.toLocaleLowerCase('pt-BR')}, prepare o conjunto de avaliação e implemente a menor jornada completa. Execute testes normais, incompletos e adversos, incluindo indisponibilidade dos sistemas e necessidade de transferência.`,
        `Entre os dias 61 e 90, pilote com grupo controlado, acompanhe resultado, custo, qualidade e exceções. Decida ${decision.toLocaleLowerCase('pt-BR')} usando o que foi observado. Só então amplie volume, canais, áreas ou autonomia.`
      ]
    },
    {
      heading: 'Conclusão: profundidade com propósito e revisão contínua',
      paragraphs: [
        `${topic} cria valor quando ajuda a concluir uma tarefa relevante com mais clareza, qualidade ou capacidade. O texto longo é útil porque reúne diagnóstico, artefato, decisão, arquitetura, risco, teste e medição; se essas partes não fossem necessárias, o artigo deveria ser menor.`,
        `O próximo passo não é publicar outra variação sobre o mesmo termo. É aplicar ${artifact.toLocaleLowerCase('pt-BR')} a casos reais, medir ${metric.toLocaleLowerCase('pt-BR')} e registrar o que mudou. Essa experiência alimenta futuras atualizações com evidência própria.`,
        `${cluster.productFit} A solução deve começar no processo e terminar em um resultado que cliente, equipe e gestão consigam verificar.`
      ]
    }
  ];

  article.sections.push(
    {
      heading: `Workbook de diagnóstico para ${lowerTopic}`,
      paragraphs: [
        `Registre esta hipótese sem suavizar o problema: “${focus.problem}”. Ao lado, descreva um episódio de ${scenario.toLocaleLowerCase('pt-BR')} com data, entrada disponível, pessoa responsável, sistema consultado e desfecho. A comparação entre hipótese e episódio mostra se a pauta representa trabalho real ou apenas uma ideia atraente.`,
        `Use ${artifact.toLocaleLowerCase('pt-BR')} como evidência de preparação. Marque o que já existe, o que depende de entrevista, o que precisa de dado e o que ainda é decisão. Para ${lowerTopic}, uma lacuna explícita é mais segura que uma resposta preenchida por suposição.`,
        `Escreva a linha de base de ${metric.toLocaleLowerCase('pt-BR')} em números absolutos e informe o período. Acrescente dois casos que deram certo, dois que falharam e um caso que a equipe não conseguiu classificar. Esse pequeno conjunto será reutilizado para conferir se o desenho melhora a realidade observada.`
      ],
      bullets: [
        `Público responsável: ${cluster.audience}.`,
        `Problema a comprovar: ${focus.problem}.`,
        `Situação representativa: ${scenario}.`,
        `Artefato exigido: ${artifact}.`,
        `Resultado acompanhado: ${metric}.`,
        `Risco que não pode ficar implícito: ${risk}.`
      ]
    },
    {
      heading: `Teste de mesa aplicado a ${focus.visualTitle.toLocaleLowerCase('pt-BR')}`,
      paragraphs: [
        `Escolha uma pessoa para representar quem inicia ${lowerTopic}, outra para operar a etapa seguinte e uma terceira para observar. Entregue somente as informações que existiriam em ${scenario.toLocaleLowerCase('pt-BR')}. Percorra o caso usando ${artifact.toLocaleLowerCase('pt-BR')} e anote toda pergunta que o artefato ainda não responde.`,
        `Repita o exercício retirando uma informação importante. A equipe precisa decidir ${decision.toLocaleLowerCase('pt-BR')} sem inventar o dado ausente. Depois introduza ${risk.toLocaleLowerCase('pt-BR')} e verifique se o fluxo bloqueia, confirma, encaminha ou registra a exceção conforme o impacto.`,
        `No encerramento, cada participante escreve qual resultado provaria a conclusão. Compare as respostas com ${metric.toLocaleLowerCase('pt-BR')}. Se operação, tecnologia e negócio usam definições diferentes, ajuste o registro antes de automatizar; código não resolve desacordo semântico.`
      ],
      bullets: [
        `Caso normal de ${lowerTopic} com todas as entradas disponíveis.`,
        `Caso incompleto relacionado a ${focus.problem.toLocaleLowerCase('pt-BR')}.`,
        `Caso de risco envolvendo ${risk.toLocaleLowerCase('pt-BR')}.`,
        `Caso em que ${artifact.toLocaleLowerCase('pt-BR')} precisa ser corrigido.`,
        `Caso que deve permanecer sob responsabilidade humana ou regra determinística.`
      ]
    },
    {
      heading: `Matriz de decisão e evidência para ${lowerTopic}`,
      paragraphs: [
        `Crie colunas para decisão, evidência mínima, fonte, responsável, alternativa e consequência. A linha mais importante deve responder a ${decision.toLocaleLowerCase('pt-BR')}. Não use “analisar” como ação final: indique quem analisa, o que compara e qual registro encerra a análise.`,
        `Na linha dedicada a ${risk.toLocaleLowerCase('pt-BR')}, separe prevenção, detecção e recuperação. A prevenção reduz ocorrência; a detecção revela que o controle falhou; a recuperação limita consequência. Uma única instrução não costuma cumprir as três funções.`,
        `Adicione uma linha de não decisão: o que acontece quando a evidência é insuficiente? Em ${scenario.toLocaleLowerCase('pt-BR')}, a resposta pode ser aguardar, pedir confirmação, manter execução atual ou encaminhar. “A IA escolhe” não é um critério auditável.`
      ],
      bullets: [
        `${topic}: decisão vinculada ao objetivo “${focus.goal}”.`,
        `${artifact}: evidência de que o processo foi compreendido.`,
        `${metric}: sinal usado para revisar a decisão depois do piloto.`,
        `${risk}: condição que aciona contenção ou escalonamento.`,
        `${focus.query}: intenção editorial que permanece concentrada nesta página.`
      ]
    },
    {
      heading: `Roteiro de avaliação por IA para ${lowerTopic}`,
      paragraphs: [
        `Entregue ao avaliador de IA o título, o público “${cluster.audience}”, o problema “${focus.problem}”, o cenário “${scenario}” e o artefato “${artifact}”. Peça saída estruturada com notas separadas para utilidade, originalidade, evidência, clareza, aderência ao negócio e qualidade técnica.`,
        `Inclua bloqueios que independem da nota: afirmação factual sem fonte, página concorrendo com a intenção “${focus.query}”, conselho inseguro relacionado a ${risk.toLocaleLowerCase('pt-BR')}, ausência de exemplo aplicável ou conclusão que não ajuda a decidir ${decision.toLocaleLowerCase('pt-BR')}.`,
        `Teste o avaliador com uma versão propositalmente genérica e outra que contenha erro evidente. Se ambas forem aprovadas, a rubrica está permissiva. Guarde o parecer, a versão e a data; a validação de ${lowerTopic} precisa ser reproduzível e contestável.`
      ],
      bullets: [
        `Utilidade: o leitor consegue avançar em ${focus.goal.toLocaleLowerCase('pt-BR')}?`,
        `Originalidade: ${artifact.toLocaleLowerCase('pt-BR')} acrescenta algo operacional?`,
        `Evidência: as fontes sustentam arquitetura e limites de ${lowerTopic}?`,
        `Clareza: o cenário de ${scenario.toLocaleLowerCase('pt-BR')} é compreensível?`,
        `Segurança: ${risk.toLocaleLowerCase('pt-BR')} possui controle verificável?`,
        `Medição: ${metric.toLocaleLowerCase('pt-BR')} tem definição utilizável?`
      ]
    },
    {
      heading: `Registro de aprendizagem e evolução de ${lowerTopic}`,
      paragraphs: [
        `Ao concluir o piloto, compare a versão inicial de ${artifact.toLocaleLowerCase('pt-BR')} com o que realmente ocorreu em ${scenario.toLocaleLowerCase('pt-BR')}. Liste premissas confirmadas, premissas rejeitadas, exceções novas e informações que a equipe passou a registrar. Esse histórico é conteúdo próprio para uma atualização futura.`,
        `Explique a variação de ${metric.toLocaleLowerCase('pt-BR')} junto de qualidade, custo e intervenção. Se o indicador melhorou porque casos difíceis foram excluídos, o ganho precisa ser apresentado com essa limitação. Se ${risk.toLocaleLowerCase('pt-BR')} apareceu, registre controle, impacto e recuperação.`,
        `A próxima versão de ${lowerTopic} deve responder ao aprendizado, não ao desejo de acrescentar funções. Escolha entre corrigir fonte, alterar regra, melhorar interface, fortalecer integração, reduzir autonomia ou ampliar escopo. Atualize a data editorial somente quando essa nova evidência modificar o conteúdo.`
      ],
      bullets: [
        `Hipótese revisada: ${focus.goal}.`,
        `Artefato atualizado: ${artifact}.`,
        `Decisão reavaliada: ${decision}.`,
        `Indicador comparado: ${metric}.`,
        `Risco observado ou testado: ${risk}.`,
        `Próxima evidência que justificará nova alteração.`
      ]
    }
  );

  return article;
}

function focus(slug, topic, promise, goal, problem, scenario, artifact, metric, risk) {
  return [
    slug,
    topic,
    promise,
    topic,
    goal,
    problem,
    scenario,
    artifact,
    metric,
    risk,
    `Definir o nível adequado de automação, controle e responsabilidade para ${topic.toLocaleLowerCase('pt-BR')}`,
    `Decisões de ${topic.toLocaleLowerCase('pt-BR')}`,
    'Escolher o próximo passo',
    `Aplique ${topic.toLocaleLowerCase('pt-BR')} a um caso real`,
  ];
}

